"""清除文件的「来自互联网」标记。"""

from .streams import ZONE_STREAM, remove_stream, stream_exists


def is_blocked(path):
    """``path`` 是否带有来自互联网的标记。"""
    return stream_exists(path, ZONE_STREAM)


def unblock(path):
    """清除 ``path`` 上的来自互联网标记。

    返回是否真的发生了变化。文件本来就没有标记时返回 ``False``，
    不抛异常（幂等）。
    """
    return remove_stream(path, ZONE_STREAM)

